class Account {
    private double balance = 100;
    void withdraw(double amt) {
        if (amt > 0 && amt <= balance) balance = balance - amt;
    }
    double getBalance() { return balance; }
}

Account a = new Account();
a.withdraw(150);
a.withdraw(30);
a.withdraw(-10);
System.out.println(a.getBalance());

What is printed?

